import{_ as o,c as a,o as l,ag as t}from"./chunks/framework.DfL_BkQ-.js";const u=JSON.parse('{"title":"下载与媒体库","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/downloads.md","filePath":"zh-CN/guide/downloads.md","lastUpdated":1791311600000}'),r={name:"zh-CN/guide/downloads.md"};function i(n,e,d,s,c,h){return l(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="下载与媒体库" tabindex="-1">下载与媒体库 <a class="header-anchor" href="#下载与媒体库" aria-label="Permalink to &quot;下载与媒体库&quot;">​</a></h1><p>nPlyr 可以把流式播放列表保存为真实文件，并让你在下载完成前就开始观看。你的历史、书签与下载内容都收录在媒体库中。</p><h2 id="下载-hls-播放列表" tabindex="-1">下载 HLS 播放列表 <a class="header-anchor" href="#下载-hls-播放列表" aria-label="Permalink to &quot;下载 HLS 播放列表&quot;">​</a></h2><p>当你把一个 <code>m3u8</code> 发送给下载器时，nPlyr 会：</p><ol><li>获取主播放列表与子播放列表（校验 HTTP 状态，并确认返回体是真正的 <code>#EXTM3U</code> 文档）。</li><li>下载每一个分片，拒绝空白或格式错误的分片行，从而让 404 错误页永远不会被误当成播放列表。</li><li>将分片重封装进 <strong>MP4</strong> 容器。</li></ol><h3 id="磁盘布局" tabindex="-1">磁盘布局 <a class="header-anchor" href="#磁盘布局" aria-label="Permalink to &quot;磁盘布局&quot;">​</a></h3><ul><li>下载中：<code>&lt;name&gt;.temp/</code></li><li>完成后：重命名为 <code>&lt;name&gt;/</code>，影片位于 <code>&lt;name&gt;/&lt;name&gt;.mp4</code>。</li><li>如果重封装失败，原始的 <code>.ts</code> 会被保留并标记为 <code>completed</code>（而非 <code>failed</code>），以免数据丢失；单个分片失败则标记为 <code>.failed</code>。</li><li>续传依据标记文件与清单工作——你可以暂停并继续。</li></ul><blockquote><p>由<a href="/zh-CN/guide/browser.html">嗅探器</a>捕获的任何自定义请求<strong>头</strong>（referer、cookie、auth）都会被保留，并随每个请求一并发送。nPlyr 绝不伪造 referer 或 origin——只会在需要时补充 user-agent。</p></blockquote><h2 id="边下边播" tabindex="-1">边下边播 <a class="header-anchor" href="#边下边播" aria-label="Permalink to &quot;边下边播&quot;">​</a></h2><p>开启此功能可<strong>边下载边观看</strong>。nPlyr 通过一个本地环回服务器提供已部分下载的文件，并领先于下载前沿开始播放（<code>progressiveLookahead = 20</code> 个分片）。它<strong>默认关闭</strong>。</p><p>边下边播生效时：</p><ul><li>播放列表的密钥（<code>#EXT-X-KEY</code>）行在交付前会被剥离，</li><li>播放器始终引用<strong>原始</strong>源 URL（本地服务器是透明的），</li><li>如果某个域名失败，该域名会在本次会话中被拉黑，部分文件会被取消并删除，且 nPlyr 不会静默改道。</li></ul><p>边下边播与去广告互斥；只有在未使用边下边播时，去广告才会接管。</p><h2 id="多清晰度与字幕" tabindex="-1">多清晰度与字幕 <a class="header-anchor" href="#多清晰度与字幕" aria-label="Permalink to &quot;多清晰度与字幕&quot;">​</a></h2><ul><li><strong>清晰度</strong>选择作用于<strong>下载</strong>（下载前挑选变体；若不挑选，nPlyr 会短暂等待选择，否则回退到最佳变体）。</li><li><strong>字幕</strong>会随媒体一起下载，并保存为分片临时目录中的 <code>subtitle.&lt;ext&gt;</code>，从而始终与文件绑定。</li></ul><h2 id="媒体库" tabindex="-1">媒体库 <a class="header-anchor" href="#媒体库" aria-label="Permalink to &quot;媒体库&quot;">​</a></h2><p>媒体库在一个可搜索的位置汇集三样东西：</p><ul><li><strong>历史</strong>——你看过什么、何时看过。</li><li><strong>书签</strong>——你保存的源与条目。</li><li><strong>下载</strong>——通过下载器保存的文件。</li></ul><p>所有内容都可通过标题搜索，并且媒体库设计为在登录同一环境的 Mac 与 iPhone 之间同步。</p><h2 id="去广告" tabindex="-1">去广告 <a class="header-anchor" href="#去广告" aria-label="Permalink to &quot;去广告&quot;">​</a></h2><p>nPlyr 使用与 Chrome 扩展拦截列表相同的<strong>订阅规则</strong>格式（即 hikerView 采用的方式）来屏蔽广告。你订阅一个过滤列表，nPlyr 便会在浏览器中以及播放期间过滤请求。这与边下边播相互独立——两者同一时间只有一个生效。</p>',21)])])}const p=o(r,[["render",i]]);export{u as __pageData,p as default};
